cd /Users/dev/workspace/vivarium/experiments/tier3/results/workspace && python3 - <<'EOF'
import json, glob

total = 0
counts = {}
kinds = {}
units = {}
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for line in f:
            rec = json.loads(line)
            kinds[rec.get('kind')] = kinds.get(rec.get('kind'), 0) + 1
            if rec.get('kind') != 'span':
                continue
            counts['span'] = counts.get('span', 0) + 1
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                counts['no_elapsed'] = counts.get('no_elapsed', 0) + 1
                continue
            v, u = el['value'], el['unit']
            units[u] = units.get(u, 0) + 1
            if u == 'ms':
                total += v
            elif u == 'us':
                total += v // 1000
            elif u == 's':
                total += v * 1000
            else:
                raise SystemExit(f'unexpected unit {u}')
print('total:', total)
print('kinds:', kinds)
print('span records:', counts.get('span'))
print('spans with no elapsed:', counts.get('no_elapsed'))
print('units seen:', units)
EOF

